export const questions = [
 {key:'goal',label:'Objetivo',text:'Hola, soy Brújula. Vamos a darle dirección a tus finanzas. ¿Qué te gustaría lograr con tu dinero?',chips:['Empezar a invertir','Crear un fondo de emergencia','Organizar mis finanzas'],type:'text'},
 {key:'currency',label:'Moneda',text:'¿En qué moneda llevas tus finanzas? Usaremos esa misma moneda para todos los montos del diagnóstico.',chips:['MXN','USD','EUR'],type:'currency'},
 {key:'income',label:'Ingreso mensual',text:'¿Cuánto recibes al mes, después de impuestos? Si varía, usa un promedio representativo.',type:'money'},
 {key:'expenses',label:'Gastos mensuales',text:'¿Cuánto gastas al mes? Incluye tus gastos esenciales y personales, pero excluye pagos de deudas e inversiones.',type:'money'},
 {key:'essentials',label:'Gastos esenciales',text:'De esos gastos, ¿cuánto corresponde a vivienda, alimentación, salud, transporte y otros básicos?',type:'money'},
 {key:'debtPayment',label:'Pago mensual de deudas',text:'¿Cuánto pagas al mes por tus deudas? Incluye tarjetas, créditos e hipoteca. Escribe 0 si no tienes.',type:'money'},
 {key:'debt',label:'Saldo de deudas',text:'¿Cuánto debes en total actualmente? Es el saldo pendiente, no el pago mensual.',type:'money'},
 {key:'savings',label:'Ahorro líquido',text:'¿Cuánto tienes ahorrado y disponible para imprevistos? Excluye inversiones que no puedas retirar fácilmente.',type:'money'},
 {key:'capital',label:'Capital adicional',text:'¿Qué monto adicional estás considerando invertir? Excluye el ahorro para emergencias que acabas de registrar. Escribe 0 si aún no lo defines.',type:'money'},
 {key:'horizon',label:'Horizonte',text:'¿Cuándo necesitarías recuperar el dinero que estás considerando invertir?',chips:['Menos de 1 año','1 a 3 años','Más de 3 años'],type:'choice'},
 {key:'experience',label:'Experiencia',text:'¿Qué experiencia tienes invirtiendo?',chips:['Estoy empezando','Ya he invertido','Tengo experiencia avanzada'],type:'choice'},
 {key:'tolerance',label:'Pérdida tolerable',text:'En un escenario de pérdida, ¿qué caída temporal podrías tolerar sin comprometer tus gastos ni cambiar de plan?',chips:['Hasta 5%','Hasta 15%','Más de 15%'],type:'choice'}
];
export function parseAmount(raw){let s=String(raw).trim().replace(/(?:MXN|USD|EUR|\$|€|\s)/gi,'');if(!/^[\d.,]+$/.test(s))return null;const comma=s.lastIndexOf(','),dot=s.lastIndexOf('.');if(comma>=0&&dot>=0){s=comma>dot?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');}else if(comma>=0){s=/^\d{1,3}(,\d{3})+$/.test(s)?s.replace(/,/g,''):s.replace(',','.');}else if((s.match(/\./g)||[]).length>1){if(!/^\d{1,3}(\.\d{3})+$/.test(s))return null;s=s.replace(/\./g,'');}const n=Number(s);return Number.isFinite(n)&&n>=0&&n<=1e12?n:null;}
export function validate(q,raw,p){if(q.type==='money'){const n=parseAmount(raw);if(n===null)return {error:'Escribe un monto válido, por ejemplo 25000 o 25,000.50. Para cero, escribe 0.'};if(q.key==='essentials'&&n>p.expenses)return {error:'Los gastos esenciales deben ser iguales o menores a tus gastos mensuales. Puedes editar tus respuestas anteriores en el diagnóstico.'};if(q.key==='debt'&&n===0&&p.debtPayment>0)return {error:'Registraste pagos de deudas. Indica el saldo pendiente o corrige el pago mensual en tus respuestas.'};return {value:n};}if(q.type==='currency'){const v=raw.trim().toUpperCase();return ['MXN','USD','EUR'].includes(v)?{value:v}:{error:'Elige MXN, USD o EUR para mantener los montos en una sola moneda.'};}if(q.type==='choice')return q.chips.includes(raw)?{value:raw}:{error:'Selecciona una de las opciones para registrar correctamente tu perfil.'};return raw.trim().length>=3?{value:raw.trim().slice(0,500)}:{error:'Cuéntame tu objetivo con un poco más de detalle.'};}
export function diagnose(p,rules={months:3,debtRatio:30}){const complete=questions.every(q=>p[q.key]!==undefined);if(!complete)return null;const free=p.income-p.expenses-p.debtPayment,base=p.essentials+p.debtPayment,target=base*rules.months,gap=Math.max(0,target-p.savings),coverage=base>0?p.savings/base:null,ratio=p.income>0?p.debtPayment/p.income*100:null;const reasons=[];if(free<=0)reasons.push('El flujo mensual no tiene excedente.');if(gap>0)reasons.push('La reserva está por debajo del objetivo configurado.');if(p.debt>0)reasons.push('Faltan tasas, plazos y condiciones de las deudas para evaluar su prioridad.');if(p.capital===0)reasons.push('Aún no has separado capital adicional para invertir.');if(p.horizon==='Menos de 1 año')reasons.push('El horizonte exige revisar la liquidez necesaria.');const status=reasons.length?'Hay prioridades por resolver':'Listo para evaluar alternativas';return {free,base,target,gap,coverage,ratio,reasons,status,reviewDebt:ratio!==null&&ratio>rules.debtRatio,monthsToTarget:free>0?Math.ceil(gap/free):null};}
export function plan(p,d,rules){const a=[];if(d.free<=0)a.push(['Recuperar margen mensual',`Tus gastos y pagos de deuda consumen tu ingreso mensual. Revisa las categorías que puedes ajustar antes de definir nuevas aportaciones.`]);else a.push(['Dar un propósito al excedente',`Tienes un excedente calculado de ${d.free.toLocaleString('es-MX')} ${p.currency} al mes. Confirma que incluimos gastos irregulares y compromisos próximos antes de asignarlo.`]);if(d.gap>0)a.push(['Completar tu reserva',`La referencia editable de ${rules.months} meses de gastos esenciales y pagos de deuda da un objetivo de ${d.target.toLocaleString('es-MX')} ${p.currency}. La diferencia con tu ahorro es ${d.gap.toLocaleString('es-MX')} ${p.currency}.${d.monthsToTarget?` Cubrirla tomaría aproximadamente ${d.monthsToTarget} meses si destinaras todo el excedente, sin considerar intereses ni cambios en tus gastos.`:''}`]);else a.push(['Revisar la reserva periódicamente','Tu ahorro cubre la referencia configurada. Confirma estabilidad de ingresos, gastos próximos y accesibilidad del dinero.']);if(p.debt>0)a.push(['Completar el análisis de deudas','Registra tasas, plazos, comisiones y condiciones de prepago para comparar el costo de tus deudas. El saldo por sí solo no determina su prioridad.']);a.push(['Evaluar opciones para tu objetivo',`Tu objetivo es «${p.goal}», con horizonte ${p.horizon.toLowerCase()}. ${d.reasons.length?'Primero completa las prioridades señaladas. Las oportunidades de stockEX pueden explorarse como información de mercado.':'Podemos comparar alternativas según liquidez, diversificación, costos y riesgo. El diagnóstico no aprueba automáticamente una acción.'}`]);a.push(['Actualizar cuando cambie tu situación','Revisa tus respuestas si cambian tus ingresos, deudas, objetivos o necesidades de liquidez. Cada señal de mercado debe conservar su fecha y su fuente.']);return a;}
